// PokeMem — 遭遇战场景卡通地形图（用户定 2026-11-17：用他发的「地図のアイコン」那种卡通地形图）
// 7 张是大图裁切的 PNG（160px、32 色量化）；大图里没有城市和洞穴，这两个按同风格手绘 SVG
// （粗深色描边 + 扁平 pastel 填色）。GitHub 推送传不了二进制文件，所以图以 base64 嵌在这里——
// 和头像 avatars.js、卡背图一个做法。母本在 ~/workspace/pokemem/img/scene-icons/（crop_icons.py、city.svg、cave.svg）。
// 图标缺失时 encounter-ui.js 回落到 imgUrl(sc.art) 的宝可梦立绘。
var SCENE_ICONS = {
  grassland: "data:image/png;base64,",
  forest: "data:image/png;base64,",
  stream: "data:image/png;base64,",
  city: "data:image/svg+xml;base64,",
  desert: "data:image/png;base64,",
  cave: "data:image/svg+xml;base64,",
  ocean: "data:image/png;base64,",
  glacier: "data:image/png;base64,",
  "champions-road": "data:image/png;base64,"
};
if (typeof module !== "undefined") module.exports = SCENE_ICONS;
